CREATE SCHEMA education;

CREATE TABLE education.courses (
    course_id text,
    course_name text,
    credits bigint,
    max_capacity bigint
);

CREATE TABLE education.enrollments (
    enrollment_id text,
    student_id text,
    course_id text,
    semester text,
    dropped boolean
);

CREATE TABLE education.excel_grades (
    grade_id text,
    enrollment_id text,
    score double precision
);

CREATE TABLE education.students (
    student_id text,
    first_name text,
    last_name text,
    enrollment_date timestamp without time zone,
    status text
);






